# name: high_alternation_pair_choice_rate
# description: Among trials where both sequences have alternation rate >= 0.6 and the rates differ, the proportion choosing the MORE alternating sequence; observed above the null means people penalise over-alternation less than the model's quadratic ideal-rate term implies, below means they penalise it more.
def test_statistic(df):
    def alt(s):
        return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(m).to_numpy(); ab = df["sequence_b"].map(m).to_numpy()
    sel = (aa >= 0.6) & (ab >= 0.6) & (np.abs(aa - ab) > 1e-9)
    if not sel.any():
        return 0.5
    chose_more = np.where(aa > ab, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    return float(chose_more[sel].mean())

# name: run_length_variety_choice_rate
# description: Among trials where the two sequences have the same alternation rate but a different number of distinct run lengths, the proportion choosing the sequence with MORE distinct run lengths; observed above the null means people prize irregular run structure beyond what the model's alternation/imbalance/streak/symmetry terms capture, below means they prefer regular run structure more than the model predicts.
def test_statistic(df):
    def feats(s):
        runs = []; cur = 1
        for x, y in zip(s, s[1:]):
            if x == y:
                cur += 1
            else:
                runs.append(cur); cur = 1
        runs.append(cur)
        return len(runs), len(set(runs))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: feats(s) for s in u}
    na = df["sequence_a"].map(lambda s: m[s][0]).to_numpy(); nb = df["sequence_b"].map(lambda s: m[s][0]).to_numpy()
    va = df["sequence_a"].map(lambda s: m[s][1]).to_numpy(); vb = df["sequence_b"].map(lambda s: m[s][1]).to_numpy()
    sel = (na == nb) & (va != vb)
    if not sel.any():
        return 0.5
    chose_more = np.where(va > vb, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    return float(chose_more[sel].mean())

# name: overall_left_choice_rate
# description: Overall proportion of trials on which the left sequence was chosen; observed above the null means people have a left-side bias the model (which has no side term) under-produces, below means a right-side bias.
def test_statistic(df):
    return float(df["chose_left"].mean())

# name: shorter_max_run_by_one_choice_rate
# description: Among trials where the two sequences' longest runs differ by exactly one flip, the proportion choosing the sequence with the SHORTER longest run; observed above the null means a one-flip-longer streak hurts more than the model's linear longest-run share (plus alternation) implies, below means it hurts less.
def test_statistic(df):
    def mr(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: mr(s) for s in u}
    ra = df["sequence_a"].map(m).to_numpy(); rb = df["sequence_b"].map(m).to_numpy()
    sel = np.abs(ra - rb) == 1
    if not sel.any():
        return 0.5
    chose_shorter = np.where(ra < rb, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    return float(chose_shorter[sel].mean())

# name: alternation_preference_participant_sd
# description: SD across participants of each person's rate of choosing the more alternating sequence (trials where alternation rates differ); observed above the null means people differ in the direction/strength of their switching preference more than the model's personal ideal rates and sensitivities produce, below means the model over-produces that heterogeneity.
def test_statistic(df):
    def alt(s):
        return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(m).to_numpy(); ab = df["sequence_b"].map(m).to_numpy()
    sel = np.abs(aa - ab) > 1e-9
    chose_more = np.where(aa > ab, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    s = pd.Series(chose_more[sel]).groupby(df["participant_id"].to_numpy()[sel]).mean()
    return float(s.std())

# name: low_alternation_pair_choice_rate
# description: Among trials where both sequences have alternation rate <= 0.5 and the rates differ, the proportion choosing the MORE alternating sequence; observed above the null means people reward extra switching among streaky sequences more strongly than the model's quadratic term implies, below means less.
def test_statistic(df):
    def alt(s):
        return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(m).to_numpy(); ab = df["sequence_b"].map(m).to_numpy()
    sel = (aa <= 0.5) & (ab <= 0.5) & (np.abs(aa - ab) > 1e-9)
    if not sel.any():
        return 0.5
    chose_more = np.where(aa > ab, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    return float(chose_more[sel].mean())
